#include <string>
#include <algorithm>

class Solution {
public:
    int countBinaryPalindromes(int n) {
        int count = 0;
        for (int x = 1; x <= n; ++x) {
            std::string b = "";
            int temp = x;
            while (temp > 0) {
                b.push_back((temp & 1) ? '1' : '0');
                temp >>= 1;
            }
            std::string rev = b;
            std::reverse(rev.begin(), rev.end());
            if (b == rev) count++;
        }
        return count;
    }
};

class Solution {
    public int countBinaryPalindromes(int n) {
        int count = 0;
        for (int x = 1; x <= n; x++) {
            String b = Integer.toBinaryString(x);
            int len = b.length();
            boolean pal = true;
            for (int i = 0; i < len / 2; i++) {
                if (b.charAt(i) != b.charAt(len - 1 - i)) {
                    pal = false;
                    break;
                }
            }
            if (pal) count++;
        }
        return count;
    }
}

